SELECT 'core-2026-09-v4','infinitive-of-purpose','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"infinitive-of-purpose","title":"Infinitive of purpose","level":"A2","order":36,"summary":"Explain the aim of an action with to and the base form of a verb.","learningGoals":["Answering why","Keep the base form","Link the action and its aim"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Answering why","explanation":"A to-infinitive can express an action’s purpose: the goal somebody intended. It answers a why question.","examples":["We stopped to admire the view.","She called to confirm the address."]},{"title":"Keep the base form","explanation":"Use to followed by the base verb, without an -ing ending. The subject of the main action can vary; the purpose verb stays in its base form.","examples":["They met to discuss the budget.","He met us to discuss the budget."]},{"title":"Link the action and its aim","explanation":"A short answer can begin with To. In a full sentence, place the purpose phrase after the main action. These tasks practise this to-infinitive pattern.","examples":["Why did you stop? To rest.","We stopped to rest."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-infinitive-of-purpose"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["A purpose infinitive explains why someone does an action. It expresses a goal, not necessarily an achieved result. The basic pattern is a main action followed by to + base verb. Its understood subject normally matches the actor in the main clause."],"rules":[{"title":"Answering why","explanation":"A to-infinitive can express an action’s purpose: the goal somebody intended. It answers a why question.","examples":["We stopped to admire the view.","She called to confirm the address.","We saved money **to buy** a new fridge."],"pattern":"Main action + **to + base verb**","paragraphs":["In I called to ask a question, I both call and intend to ask. The to-infinitive supplies the purpose. The verb after to stays in base form regardless of the subject or the tense of the main action. I called to asked incorrectly marks the second verb as past."],"id":"infinitive-of-purpose-foundation-1","domain":"nonfinite","referenceIds":["bc-infinitive-of-purpose"],"readingVersion":"foundations-2026-09-v2"},{"title":"Keep the base form","explanation":"Use to followed by the base verb, without an -ing ending. The subject of the main action can vary; the purpose verb stays in its base form.","examples":["They met to discuss the budget.","He met us to discuss the budget.","I spoke quietly **in order not to disturb** them."],"pattern":"**Why** did you call? — **To ask** a question.","paragraphs":["In order to and so as to can make purpose explicit. Negative purpose normally uses in order not to or so as not to. Ordinary not to is possible in some contexts, but a clear full pattern is useful for learners."],"id":"infinitive-of-purpose-foundation-2","domain":"nonfinite","referenceIds":["bc-infinitive-of-purpose"],"readingVersion":"foundations-2026-09-v2"},{"title":"Link the action and its aim","explanation":"A short answer can begin with To. In a full sentence, place the purpose phrase after the main action. These tasks practise this to-infinitive pattern.","examples":["Why did you stop? To rest.","We stopped to rest.","She moved aside **so that I could pass**."],"pattern":"**in order not to** wake anyone","paragraphs":["If the intended actor changes, a so that clause is often clearer: I opened the door so that she could enter. The purpose can be placed first, often followed by a comma, when it frames the whole sentence."],"id":"infinitive-of-purpose-foundation-3","domain":"nonfinite","referenceIds":["bc-infinitive-of-purpose"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"For + -ing often describes an object’s function: a brush for cleaning bottles. It is not the normal substitute for a person’s purpose in I went to the shop to buy milk. A purpose does not prove success: she hurried to catch the bus but missed it is coherent.","examples":["We saved money **to buy** a new fridge.","I spoke quietly **in order not to disturb** them.","She moved aside **so that I could pass**."],"id":"infinitive-of-purpose-foundation-4","domain":"nonfinite","referenceIds":["bc-infinitive-of-purpose"],"readingVersion":"foundations-2026-09-v2"},{"domain":"nonfinite","id":"for-subject-and-tough","title":"For + subject, infinitival relatives and tough constructions","explanation":"For can introduce an explicit subject of a to-infinitive. An infinitive can also modify a noun or follow an adjective with an understood object linked to the main subject. In This book is easy to read, the book is what someone reads. These links explain why a repeated object pronoun is usually unnecessary.","pattern":"a place **to stay** / **for us to stay**","examples":["It is important **for everyone to know**.","The problem is **hard to solve**."],"commonMistakes":["For her to leave expresses the infinitive’s subject; to her is not interchangeable. This problem is hard to solve it repeats an object already understood from the main subject."],"referenceIds":["cambridge-nonfinite-scope","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["Main action + **to + base verb**","**Why** did you call? — **To ask** a question.","**in order not to** wake anyone"],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["past-habits"],"readingReferenceIds":["bc-infinitive-of-purpose","cambridge-nonfinite-scope","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='infinitive-of-purpose'
